"use client";
/* Avatar, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Avatar(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("avatar"); }, []);
  return React.createElement("piix-avatar", piixAttrs(props));
}

export default Avatar;
